def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    upper = grid[:sep]
    lower = grid[sep + 1:]
    h, w = len(upper), len(grid[0])

    # Mark positions where both layers contain their non-background symbol.
    top_counts = {}
    bot_counts = {}
    for row in upper:
        for x in row:
            top_counts[x] = top_counts.get(x, 0) + 1
    for row in lower:
        for x in row:
            bot_counts[x] = bot_counts.get(x, 0) + 1

    top_bg = max(top_counts, key=top_counts.get)
    bot_bg = max(bot_counts, key=bot_counts.get)
    top_mark = min((x for x in top_counts if x != top_bg), key=lambda x: top_counts[x])
    bot_mark = min((x for x in bot_counts if x != bot_bg), key=lambda x: bot_counts[x])

    return [
        [3 if upper[r][c] == top_mark and lower[r][c] == bot_mark else top_mark
         for c in range(w)]
        for r in range(h)
    ]
